#!/usr/bin/env bash
# GENERATED by scripts/derive-cpu.py from scripts/cpu-variant/smoke-inner.sh.
#
# Headless planning-simulator drive, run inside the GPU-free test image by
# test/smoke.sh. Passes when the vehicle, engaged in autonomous mode through the
# AD API, moves more than 2 m toward the goal. Start and goal are on lanelet 102
# of sample-map-planning, 10 % and 85 % along it (MGRS 54SVE local coordinates).
# No `set -u`: the ROS setup scripts read unset variables.
source /opt/autoware/1.5.0/setup.bash
export RMW_IMPLEMENTATION=rmw_cyclonedds_cpp
export ROS_DOMAIN_ID=87
MAP=/opt/autoware/1.5.0/share/autoware_maps/sample-map-planning
# autoware-full pulls in the sample maps only from 1.9.0 on; before that they
# are their own package, autoware-maps-<version>, in the same localrepo.
if [ ! -f "$MAP/pointcloud_map.pcd" ]; then
  PKG=autoware-maps-$(echo 1.5.0 | tr . -)
  echo "installing $PKG..."
  apt-get install -y -qq "$PKG" >/dev/null || { echo "SMOKE FAIL: cannot install the sample map"; exit 1; }
fi

ros2 launch autoware_launch planning_simulator.launch.xml \
  map_path:=$MAP vehicle_model:=sample_vehicle sensor_model:=sample_sensor_kit \
  rviz:=false > /tmp/launch.log 2>&1 &
LPID=$!

echo "waiting for the stack..."
for _ in $(seq 1 60); do
  ros2 service list 2>/dev/null | grep -q /api/routing/set_route_points && break
  sleep 3
done
sleep 20
echo "nodes up: $(ros2 node list 2>/dev/null | wc -l)"

call() {
  timeout 30 ros2 service call "$@" | grep -oE 'success=(True|False)[^)]*'
}
POSE='position: {x: 3648.21, y: 73507.02, z: 19.5}, orientation: {z: 0.750454, w: 0.660922}'
GOAL='position: {x: 3637.82, y: 73588.56, z: 19.5}, orientation: {z: 0.750454, w: 0.660922}'
echo "initialize: $(call /api/localization/initialize autoware_adapi_v1_msgs/srv/InitializeLocalization \
  "{pose: [{header: {frame_id: map}, pose: {pose: {$POSE}}}]}")"
sleep 5
echo "route:      $(call /api/routing/set_route_points autoware_adapi_v1_msgs/srv/SetRoutePoints \
  "{header: {frame_id: map}, goal: {$GOAL}}")"
sleep 10
echo "engage:     $(call /api/operation_mode/change_to_autonomous autoware_adapi_v1_msgs/srv/ChangeOperationMode "{}")"

y() { timeout 10 ros2 topic echo --once /localization/kinematic_state --field pose.pose.position.y 2>/dev/null | head -1; }
y0=$(y); sleep 25; y1=$(y)
echo "y: $y0 -> $y1 (goal 73588.56)"

died=$(grep -E 'process has died' /tmp/launch.log | head -10)
[ -n "$died" ] && echo "died processes:" && echo "$died"
kill -INT $LPID; sleep 5

python3 - "$y0" "$y1" <<'EOF'
import sys
try:
    d = abs(float(sys.argv[2]) - float(sys.argv[1]))
except ValueError:
    print("SMOKE FAIL: no /localization/kinematic_state"); sys.exit(1)
print(f"moved {d:.1f} m: {'SMOKE PASS' if d > 2.0 else 'SMOKE FAIL'}")
sys.exit(0 if d > 2.0 else 1)
EOF
